ruleToc.chapterList:
+<js>
var n=result.match(/共(\d+)页/)[1];
var list=[{k:'1',v:baseUrl}];
for(var i=2;i<=n;i++){
list.push({k:''+i,v:baseUrl.replace(/\.html/,'_'+i+'.html')});
}
list
</js>

ruleSearch.coverUrl:
class.s2@tag.a.0@href<js>
var id = result.match(/(\d+)\/?$/)[1];
var iid = parseInt(id/1000);
source.bookSourceUrl + 'files/article/image/'+iid+'/'+id+'/'+id+'s.jpg';
</js>

